					updateLspStatus: () => {},
					resetLSPService: () => {},
				} as any),
			);
			fs.writeFileSync(existingPath, "(function(){ return 2; })();\n");
			fs.writeFileSync(directPath, "const direct = 2;\n");
			const handler = handleToolResult({
				event: {
					toolName: "bash",
					toolCallId: "3568-bash",
					input: { command },
					content: [{ type: "text", text: "extracted" }],
