/**
 * #4576: `~` on a host-supplied tool path. The tool_call seam
 * (`resolveToolCallFilePath` -> `resolveHostToolPath`) expands it, but the
 * tool_result seam used a bare `path.resolve`, so `~/proj/a.ts` became
 * `<projectRoot>/~/proj/a.ts` — a path that never existed — and that phantom
 * reached runner dispatch (biome `internalError/io`, then a synthetic
 * `coverage-unavailable` notice for a file the agent never touched).
 *
 * HOME/USERPROFILE are pinned to a directory below the test tmp root so
 * `os.homedir()` points there: the real maintainer home is never read or
 * written.
 */
describe("host tool path resolution on the tool_result side (#4576)", () => {
	function callDeps(runtime: RuntimeCoordinator, event: unknown) {
		return {
			event,
			ctx: { cwd: runtime.projectRoot },
			lensEnabled: true,
			getFlag: (name: string) => name === "no-lsp" || name === "no-complexity",
			dbg: () => {},
			runtime,
			cacheManager: new CacheManager(false),
			ensureLSPConfigInitialized: async () => {},
			updateLspStatus: () => {},
			resetLSPService: () => {},
		} as never;
	}
	function resultDeps(runtime: RuntimeCoordinator, event: unknown) {
		return {
			event,
			getFlag: (name: string) => name === "no-lsp" || name === "no-complexity",
			dbg: () => {},
			runtime,
			cacheManager: new CacheManager(false),
			biomeClient: {},
			ruffClient: {},
			metricsClient: {},
			resetLSPService: () => {},
			readGuard: runtime.readGuard,
			agentBehaviorRecord: () => [],
			formatBehaviorWarnings: () => "",
		} as never;
	}
	async function writeThroughRealSeams(
		runtime: RuntimeCoordinator,
		toolCallId: string,
		spelling: string,
	) {
		const input = { path: spelling, content: "export const value = 1;\n" };
		await runHandlerExpectingNoThrow(() =>
			handleToolCall(
				callDeps(runtime, { toolName: "write", toolCallId, input }),
			),
		);
		await handleToolResult(
			resultDeps(runtime, {
				toolName: "write",
				toolCallId,
				input,
				content: [{ type: "text", text: "ok" }],
			}),
		);
	}
	/** The `filePath` every runner dispatch was handed, in call order. */
	function dispatchedPaths(): string[] {
		return vi
			.mocked(runPipeline)
			.mock.calls.map(([ctx]) => (ctx as { filePath?: string }).filePath ?? "");
	}

	it("dispatches the expanded home path, never the phantom <root>/~/ path", async () => {
		const env = setupTestEnvironment("pi-lens-4576-tilde-");
		// The fixture HOME sits under the checkout, not under os.tmpdir():
		// `isPiOwnedTempPath` treats every `<tmp>/pi-*` root as pi-lens
		// internal, and pi-lens would then skip the file for a reason unrelated
		// to the path this test pins. `process.cwd()` is the repo root, which
		// the mkdtemp-parent census exempts.
		const homeRoot = fs.mkdtempSync(
			path.join(process.cwd(), ".probe-4576-home-"),
		);
		const home = path.join(homeRoot, "home");
		const projectRoot = path.join(env.tmpDir, "workspace");
		const realFile = path.join(home, "proj", "src", "tilde.ts");
		fs.mkdirSync(path.dirname(realFile), { recursive: true });
		fs.mkdirSync(projectRoot, { recursive: true });
		fs.writeFileSync(path.join(home, "proj", "package.json"), "{}\n");
		fs.writeFileSync(realFile, "export const value = 1;\n");
		const restoreHome = pinTestHome(home);
		const runPipelineMock = vi.mocked(runPipeline);
		runPipelineMock.mockReset();
		runPipelineMock.mockResolvedValue({
			output: "",
			hasBlockers: false,
			isError: false,
			fileModified: false,
		} as never);
		try {
			// The pin is live before the handler runs: a stale HOME would make
			// every assertion below pass against the wrong directory.
			expect(os.homedir()).toBe(home);
			const runtime = new RuntimeCoordinator();
			runtime.projectRoot = projectRoot;
			const phantom = path.join(projectRoot, "~", "proj", "src", "tilde.ts");

			await writeThroughRealSeams(
				runtime,
				"call-4576-tilde",
				"~/proj/src/tilde.ts",
			);

			expect(dispatchedPaths()[0]).toBe(realFile);
			// The phantom path is where the pre-fix resolver landed. No runner
			// may ever be dispatched for it: it is what produced the ghost
			// biome `internalError/io` and the synthetic coverage notice.
			expect(dispatchedPaths()).not.toContain(phantom);
			expect(
				dispatchedPaths().some((p) => p.includes(`${path.sep}~${path.sep}`)),
			).toBe(false);
		} finally {
			restoreHome();
			removeTempDirSync(homeRoot);
			env.cleanup();
		}
	});

	// #4577 N1: `~/x` is the spelling whose behaviour CHANGED, and the case
	// above drives it end to end. `~user/x` did NOT change (pi expands only `~`
	// and `~/`, and the pre-fix ternary also resolved a named-user tilde
	// against the base), so this is an agreement witness, not a regression
	// test: it reds if the two seams ever diverge again, which is the whole
	// defect #4576 fixed.
	it("leaves a ~user path resolved against the base, as the tool_call seam does", async () => {
		const env = setupTestEnvironment("pi-lens-4577-resolver-");
		const home = path.join(env.tmpDir, "home");
		const projectRoot = path.join(env.tmpDir, "workspace");
		const userFile = path.join(projectRoot, "~user", "proj", "a.ts");
		fs.mkdirSync(home, { recursive: true });
		fs.mkdirSync(path.dirname(userFile), { recursive: true });
		fs.writeFileSync(userFile, "export const a = 1;\n");
		const restoreHome = pinTestHome(home);
		const runPipelineMock = vi.mocked(runPipeline);
		runPipelineMock.mockReset();
		runPipelineMock.mockResolvedValue({
			output: "",
			hasBlockers: false,
			isError: false,
			fileModified: false,
		} as never);
		try {
			expect(os.homedir()).toBe(home);
			const runtime = new RuntimeCoordinator();
			runtime.projectRoot = projectRoot;
			await writeThroughRealSeams(runtime, "call-4577-user", "~user/proj/a.ts");
			expect(dispatchedPaths()[0]).toBe(userFile);
		} finally {
			restoreHome();
			env.cleanup();
		}
	});

	// PIN, not a regression test: a bare `~` resolves to the home DIRECTORY, so
	// no write result can target it and the handler has no effect to observe.
	// The pin keeps the resolver's third spelling from drifting silently.
	it("pins ~ resolving to the home directory itself", () => {
		const env = setupTestEnvironment("pi-lens-4577-resolver-");
		const home = path.join(env.tmpDir, "home");
		const cwd = path.join(env.tmpDir, "workspace");
		fs.mkdirSync(home, { recursive: true });
		fs.mkdirSync(cwd, { recursive: true });
		const restoreHome = pinTestHome(home);
		try {
			expect(os.homedir()).toBe(home);
			expect(resolveHostToolPath("~", cwd)).toBe(home);
		} finally {
			restoreHome();
			env.cleanup();
		}
	});

	// #4577 (Greptile P1): a bash-derived synthetic write's path came FROM disk,
	// so its bytes are the identity. Re-resolving it through the host-tool
	// resolver folded U+202F to a space and dispatched `src/a b.ts` — a file that
	// does not exist — for a write that landed at `src/a\u202Fb.ts`. The
	// recovery caller states the provenance (`_pathAlreadyResolved`); nothing
	// re-detects it downstream.
	it("dispatches a recovered write's byte-exact path, never the folded spelling", async () => {
		const env = setupTestEnvironment("pi-lens-4577-recovered-");
		const projectRoot = path.join(env.tmpDir, "workspace");
		const writtenFile = path.join(projectRoot, "src", "a\u202Fb.ts");
		const foldedFile = path.join(projectRoot, "src", "a b.ts");
		fs.mkdirSync(path.dirname(writtenFile), { recursive: true });
		fs.writeFileSync(writtenFile, "export const a = 1;\n");
		const runPipelineMock = vi.mocked(runPipeline);
		runPipelineMock.mockReset();
		runPipelineMock.mockResolvedValue({
			output: "",
			hasBlockers: false,
			isError: false,
			fileModified: false,
		} as never);
		try {
			const runtime = new RuntimeCoordinator();
			runtime.projectRoot = projectRoot;
			await handleToolResult(
				resultDeps(runtime, {
					toolName: "bash",
					toolCallId: "call-4577-recovered",
					input: { command: "tee 'src/a\u202Fb.ts'" },
					content: [{ type: "text", text: "export const a = 1;" }],
				}),
			);
			expect(dispatchedPaths()).toContain(writtenFile);
			expect(dispatchedPaths()).not.toContain(foldedFile);
		} finally {
			env.cleanup();
		}
	});
});

tests/clients/test-utils.ts:
import * as fs from "node:fs";
import * as net from "node:net";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, vi } from "vitest";
import {
	getTmpRootRegistry,
	registerTmpRoot,
} from "../support/tmp-root-registry.js";

// A just-used temp dir can still be written to after the owning test is done:
// a Windows file handle held briefly after a child/watcher/background scan
// exits (AV scanning, delayed handle release, #793, #810), or — measured on
// Linux, #4081 — a grandchild of a SIGKILLed real child still writing under
// the scratch home. An immediate recursive `rm` then throws EPERM/ENOTEMPTY.
// Node's in-call `maxRetries` does not recover that on Node 22 (it stalls
// ~3 s and still throws), so this loops over FRESH `rmSync` calls, each one
// re-walking the directory, for at most REMOVE_BUDGET_MS in total. If the dir
// is STILL there, a leftover temp dir under the OS temp root is harmless (the
// OS reclaims it eventually) while failing the whole test run over teardown
// is not — so the final failure warns instead of throwing. This is the ONE
// shared cleanup helper for test temp dirs (#810's pattern-class rule) —
// route every ad-hoc `fs.rmSync(dir, { recursive: true, force: true })`
// teardown through this instead of hand-rolling retries per suite.
const REMOVE_BUDGET_MS = 2_000;
const REMOVE_RETRY_MS = 50;
// The errnos Node's own `maxRetries` retries; anything else is not transient.
const RETRYABLE_REMOVE_CODES = new Set([
	"EBUSY",
	"EMFILE",
	"ENFILE",
	"ENOTEMPTY",
	"EPERM",
]);
export function removeTempDirSync(dir: string): void {
	const deadline = Date.now() + REMOVE_BUDGET_MS;
	for (;;) {
		try {
			fs.rmSync(dir, { recursive: true, force: true });
			return;
		} catch (err) {
			const code = (err as NodeJS.ErrnoException).code;
			if (
				code === undefined ||
				!RETRYABLE_REMOVE_CODES.has(code) ||
				Date.now() >= deadline
			) {
				process.stderr.write(
					`[test cleanup] could not remove temp dir ${dir}: ${
						err instanceof Error ? err.message : String(err)
					}\n`,
				);
				return;
			}
			Atomics.wait(
				new Int32Array(new SharedArrayBuffer(4)),
				0,
				0,
				REMOVE_RETRY_MS,
			);
		}
	}
}

export function setupTestEnvironment(prefix = "pi-lens-test-"): {
	tmpDir: string;
	cleanup: () => void;
} {
	const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
	activeTestEnvironments.add(tmpDir);
	// #2912: the shared setup removes this root at file teardown and on SIGTERM,
	// so a timeout or a failed assertion before `cleanup()` cannot leak it.
	registerTmpRoot(getTmpRootRegistry(), tmpDir, "registered");
	return {
		tmpDir,
		cleanup: () => {
			removeTempDirSync(tmpDir);
			// Keep the root tracked: deferred work can recreate it before the
			// owning family's cleanup sweep runs.
		},
	};
}

const activeTestEnvironments = new Set<string>();

export function cleanupTestEnvironments(
	prefix: string,
	options: { untrack?: boolean } = {},
): void {
	for (const tmpDir of activeTestEnvironments) {
		if (!path.basename(tmpDir).startsWith(prefix)) continue;
		removeTempDirSync(tmpDir);
		if (options.untrack !== false && !fs.existsSync(tmpDir)) {
			activeTestEnvironments.delete(tmpDir);
		}
	}
}

type WriterModule = Record<string, unknown>;

/**
 * Every copy of a writer module a drain has reached, keyed by subsystem. A
 * test that calls `vi.resetModules()` can leave queued writes on an earlier
 * copy (the one its top-level import holds) or on a later one (the one it
 * re-imported), so a drain waits on each copy it has seen, not only the
 * current one.
 */
const seenWriterModules = new Map<string, Set<WriterModule>>();

async function drainWriter(
	name: string,
	load: () => Promise<WriterModule>,
	hooks: readonly string[],
): Promise<void> {
	let copies = seenWriterModules.get(name);
	if (!copies) {
		copies = new Set();
		seenWriterModules.set(name, copies);
	}
	try {
		copies.add(await load());
	} catch {
		// The module failed to load under this file's mocks: nothing new to add.
	}
	for (const mod of copies) {
		for (const hook of hooks) {
			try {
				const fn = mod[hook];
				if (typeof fn === "function") await fn();
			} catch {
				// Mocked without the hook, or the hook failed: nothing to drain.
			}
		}
	}
}

/**
 * Wait for every known background writer that can recreate a fixture root
 * after its test removed it: review-graph persists, project-snapshot body
 * persists, extension-log appends, and the resident jscpd scan (#4505). Each
 * costs nothing when idle.
 *
 * The modules are loaded here, at call time, never at the top of this file,
 * so a file that never touched a writer pays only the import. Skipped under
 * fake timers; restore real timers first.
 *
 * Gap: a copy is only seen once a drain runs while it is the current copy. A
 * file that resets modules before its first drain, while its top-level import
 * still has writes queued, must drain that copy itself.
 */
export async function drainBackgroundWritesForTests(): Promise<void> {
	// The waits poll on `setTimeout`, which never fires under fake timers.
	if (vi.isFakeTimers()) return;
	await drainWriter(
		"review-graph",
		() => import("../../clients/review-graph/builder.js"),
		["flushReviewGraphPersistsForTests", "waitForReviewGraphPersistsForTests"],
	);
	await drainWriter(
		"project-snapshot",
		() => import("../../clients/project-snapshot.js"),
		["waitForProjectSnapshotPersistsForTests"],
	);
	await drainWriter(
		"extension-log",
		() => import("../../clients/extension-log.js"),
		["flushExtensionLog"],
	);
	// #4505: a session_start jscpd scan is fire-and-forget, so a file that ends
	// right after its last turn strands the report directory (the 4403 cascade
	// file, in the pre-push batch). Every drained cleanup waits for it.
	await drainResidentJscpdScans();
}

/**
 * Drain in-flight jscpd scans started by the resident analyzer bootstrap before
 * a test removes its fixture roots (#4133). A session-start jscpd scan is
 * fire-and-forget; if the test file ends while one is still running, Vitest
 * SIGTERMs the worker before the scan's `finally` removes its report directory
 * and the `pi-lens-jscpd-*` entry is stranded in the shared tmpdir. The
 * `JscpdClient.shutdown()` barrier (#3338) waits for it. `peek` resolves the
 * already-loaded client without forcing a load, and the method is optional so a
 * stub bootstrap double is a no-op rather than a crash.
 */
export async function drainResidentJscpdScans(): Promise<void> {
	const { peekBootstrapClients } = await import("../../clients/bootstrap.js");
	const client = peekBootstrapClients()?.jscpdClient as
		| { shutdown?: () => Promise<void> }
		| undefined;
	await client?.shutdown?.();
}

/**
 * Drain deferred fixture producers before the final cleanup pass. Keeping
 * roots tracked until the last tick preserves the hygiene sweep's handle.
 * The known background writers are drained first unless `drainWrites` is
 * false.
 */
export async function cleanupTestEnvironmentsDrained(
	prefix: string,
	options: {
		beforeDrain?: () => Promise<void>;
		drainWrites?: boolean;
	} = {},
): Promise<void> {
	await options.beforeDrain?.();
	if (options.drainWrites !== false) await drainBackgroundWritesForTests();
	for (let tick = 0; tick < 3; tick++) {
		await new Promise<void>((resolve) => setImmediate(resolve));
		if (tick === 2) {
			// The final producer turn can be queued by the preceding drain.
			await new Promise<void>((resolve) => setImmediate(resolve));
		}
		cleanupTestEnvironments(prefix, { untrack: tick === 2 });
	}
}

/**
 * Register an `afterEach` that drains and removes every root created through
 * `setupTestEnvironment` with one of `prefixes`. Call it at file or describe
 * scope, and create the file's temp roots with `setupTestEnvironment`.
 */
export function useTrackedTempDirs(...prefixes: string[]): void {
	afterEach(async () => {
		// The drain below parks on `setImmediate`, which a fake-timer test has
		// replaced. Vitest runs `afterEach` hooks in reverse registration order, so
		// this hook runs BEFORE the file's own `vi.useRealTimers()` teardown and
		// hung to the 10 s hook timeout, failing the faking test and every test
		// after it (launch.test.ts on Windows, #4019). Restore the real clock first.
		vi.useRealTimers();
		for (const prefix of prefixes) await cleanupTestEnvironmentsDrained(prefix);
	});
}

/**
 * A file reachable under TWO spellings that differ only in case, where the
 * kernel reports the on-disk spelling for both — the exact contract
 * `normalizeFilePath`'s POSIX arm depends on (#3098, the live half of #1024:
 * a raw mis-cased `lens_diagnostic_mark` write and a `normalizeMapKey` read
 * deriving two anchors for one file, so the agent's own mark never applies).
 *
 * Built natively where the filesystem is case-insensitive (macOS APFS/HFS+,
 * Windows, `nocase` vfat/ntfs3/cifs). On a case-sensitive filesystem — the
 * ubuntu Unit tests lane — the same observable contract is manufactured with a
 * case-variant symlink (`SUB` → `sub`): `existsSync(SUB/a.ts)` is true and
 * `realpathSync.native` returns `sub/a.ts`, byte-identical to what APFS
 * answers, so the seam under test cannot tell the two fixtures apart and the
 * guard runs on EVERY lane instead of skipping on the one CI actually has.
 *
 * `skipReason` is set — and the case cases must skip visibly — only where the
 * kernel cannot supply that contract: a Linux ext4/tmpfs casefold directory
 * aliases the spellings but `realpath(3)` returns the QUERIED casing (measured
 * in #3154), so there is nothing for the normalizer to canonicalize toward.
 */
export function createCaseAliasFixture(
	baseDir: string,
	options: { dirName?: string; fileName?: string; content?: string } = {},
): {
	/** Mis-cased spelling, as a raw `path.resolve(cwd, arg)` would carry it. */
	rawMisCased: string;
	/** The spelling really on disk. */
	onDisk: string;
	/** Set when this filesystem cannot report on-disk casing (see above). */
	skipReason?: string;
} {
	const dirName = options.dirName ?? "sub";
	const fileName = options.fileName ?? "a.ts";
	const onDiskDir = path.join(baseDir, dirName);
	fs.mkdirSync(onDiskDir, { recursive: true });
	const onDisk = path.join(onDiskDir, fileName);
	fs.writeFileSync(onDisk, options.content ?? "const target = bad();\n");

	const misCasedDir = path.join(baseDir, dirName.toUpperCase());
	const rawMisCased = path.join(misCasedDir, fileName);
	if (!fs.existsSync(rawMisCased)) {
		try {
			fs.symlinkSync(dirName, misCasedDir, "dir");
		} catch (err) {
			return {
				rawMisCased,
				onDisk,
				skipReason: `cannot alias ${dirName} as ${dirName.toUpperCase()}: ${
					err instanceof Error ? err.message : String(err)
				}`,
			};
		}
	}
	let canonical: string | undefined;
	try {
		canonical = fs.realpathSync.native(rawMisCased);
	} catch {
		canonical = undefined;
	}
	return canonical === undefined || canonical === rawMisCased
		? {
				rawMisCased,
				onDisk,
				skipReason:
					"filesystem aliases the two spellings but reports the QUERIED casing, " +
					"not the on-disk one (Linux casefold directory) — refs #3154",
			}
		: { rawMisCased, onDisk };
}

export function createTempFile(
	baseDir: string,
	relativePath: string,
	content: string,
): string {
	const filePath = path.join(baseDir, relativePath);
	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, content);
	return filePath;
}

/**
 * Point `os.homedir()` at `home` for the rest of the test and return the undo.
 *
 * `homedir()` reads `HOME` (Windows: `USERPROFILE`) on every call, so pinning
 * both is what makes a `~` path expand inside a temp root instead of the
 * maintainer's real home. The caller restores in a `finally`: a failing
 * assertion must not leave the process pointed at a temp directory that the
 * next test then reads.
 */
export function pinTestHome(home: string): () => void {
	const previousHome = process.env.HOME;
	const previousUserProfile = process.env.USERPROFILE;
	process.env.HOME = home;
	process.env.USERPROFILE = home;
	return () => {
		if (previousHome === undefined) delete process.env.HOME;
		else process.env.HOME = previousHome;
		if (previousUserProfile === undefined) delete process.env.USERPROFILE;
		else process.env.USERPROFILE = previousUserProfile;
	};
}

/** How a connect to a Unix socket path ends: `connected` when a server
 *  listens there, otherwise the errno code (a stale socket or a regular file
 *  refuses with `ECONNREFUSED`). */
export function connectOutcome(endpoint: string): Promise<string> {
	return new Promise((resolve) => {
		const probe = net.createConnection(endpoint);
		probe.once("connect", () => {
			probe.destroy();
			resolve("connected");
		});
		probe.once("error", (error) =>
			resolve((error as NodeJS.ErrnoException).code ?? String(error)),
		);
	});
}

/** Leave a stale Unix socket file at `file`, as a killed host does, without a
 *  child process: bind, move the file aside so the close-time unlink finds
 *  nothing, close the listener, move the file back. */
export async function plantStaleUnixSocket(file: string): Promise<void> {
	const parked = `${file}.parked`;
	const server = net.createServer();
	await new Promise<void>((resolve, reject) => {
		server.once("error", reject);
		server.listen(file, resolve);
	});
	fs.renameSync(file, parked);
	await new Promise<void>((resolve) => server.close(() => resolve()));
	fs.renameSync(parked, file);
}

tests/config/glossary-synonym-sweep.test:
/**
 * #3259 synonym-retirement sweep.
 *
 * The glossary is the source of truth. This census reads it at test time,
 * blanks comments and strings, and counts only whole TypeScript identifier
 * tokens in the runtime source population. A retired synonym in prose, a
 * string (including template text), or a larger identifier such as
 * `blockerCount` is not a code-vocabulary use. `${...}` remains code because
 * the shared stripper lexes template interpolations as ordinary source.
 *
 * Multi-word retired phrases and hyphenated phrases are deliberately listed
 * below as non-identifiers. They cannot be declaration/member identifiers;
 * any evidence for them is prose or a string literal and is therefore outside
 * this lexical sweep. There are no identifier needles with string-only
 * evidence in this population, so no `codeMatches` exception is needed.
 *
 * The pins are the rename inventory for #3259, held to EXACT equality per
 * `(term, file)`. `auditSymbolCounts` alone cannot do that: `auditRegistry`
 * is deliberately asymmetric, so a REGISTERED `file@count` row the scan no
 * longer flags passes. Round 2 shipped exactly that hole — deleting five live
 * `warning` identifiers from `clients/runtime-turn.ts` left the suite green
 * (#3279 G-3279-4), which is the #3256 M3c stale-pin failure again. Equality
 * is therefore audited as TWO calls with the roles swapped, each carrying its
 * own message, so a rename slice knows which direction it hit:
 *   - `UNPINNED live uses` — live rows the pin does not name (grow).
 *   - `STALE pins` — pinned rows the live census no longer produces (shrink).
 * Both clean means the two `file@count` key sets are equal.
 *
 * Glossary retirement grammar: each declaration is a bullet whose bold term
 * is followed by `retires` plus one or more backtick-delimited synonyms,
 * ending at the declaration's period. A bullet mentioning `retires` that
 * does not match this grammar is malformed and must fail loudly.
 *
 * A spelling can be BOTH canonical for its own concept and retired by another
 * concept (`finding` retires `diagnostic`, while `diagnostic` is canonical at
 * `clients/dispatch/types.ts`). Those `retired-in-one-sense` terms are
 * excluded from the global census — a lexical spelling count cannot tell the
 * two senses apart — so the exclusion itself is pinned as a DERIVED list of
 * `term -> owning module -> retiring concept`, read out of the glossary's own
 * `owned by` clause. Every per-concept rename slice under #3259 works from
 * that list, and a new collision reds it instead of vanishing silently
 * (#3279 G-3279-2).
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
	assertNonEmptyScan,
	auditSymbolCounts,
	listSourceFiles,
	readWalkedFile,
	relativePosix,
	stripSource,
} from "../support/sweep-kit.js";

const REPO_ROOT = path.resolve(
	path.dirname(fileURLToPath(import.meta.url)),
	"../..",
);

const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

function agentsText(): string {
	return fs.readFileSync(
		process.env.PI_LENS_AGENTS_PATH ?? path.join(REPO_ROOT, "AGENTS.md"),
		"utf8",
	);
}

/** One parsed glossary declaration: the module that owns it, and what it retires. */
interface GlossaryEntry {
	/** The module named by the bullet's `owned by` clause. */
	owner: string;
	retires: string[];
}

function parseGlossary(source = agentsText()): Map<string, GlossaryEntry> {
	const glossary = source
		.split("## Glossary", 2)[1]
		?.split("Where two spellings", 2)[0];
	if (!glossary) throw new Error("AGENTS.md glossary is missing");

	const parsed = new Map<string, GlossaryEntry>();
	for (const line of glossary.split("\n")) {
		const match = /^- \*\*([^*]+)\*\* .*?\bretires\s+(.+?)(?=\.\s|$)/.exec(
			line,
		);
		if (!match) {
			if (/\bretires\b/.test(line)) {
				throw new Error(`malformed glossary retirement declaration: ${line}`);
			}
			continue;
		}
		const synonyms = [...match[2].matchAll(/`([^`]+)`/g)].map(
			([, synonym]) => synonym,
		);
		if (synonyms.length === 0) {
			throw new Error(
				`glossary term has no parsed retired synonyms: ${match[1]}`,
			);
		}
		// An absent `owned by` clause needs no guard of its own: the owner lands
		// in the pinned `retired-in-one-sense` list, so it reds there.
		parsed.set(match[1], {
			owner: /\bowned by `([^`]+)`/.exec(line)?.[1] ?? "",
			retires: synonyms,
		});
	}
	return parsed;
}

function identifierTerms(glossary: Map<string, GlossaryEntry>): string[] {
	const canonicalTerms = new Set(glossary.keys());
	return [
		...new Set(
			[...glossary.values()]
				.flatMap((entry) => entry.retires)
				.filter((term) => IDENTIFIER.test(term) && !canonicalTerms.has(term)),
		),
	].sort();
}

/** A spelling that is canonical for one concept and retired by another. */
interface OneSenseRow {
	term: string;
	/** The module the glossary says owns the CANONICAL sense. */
	owner: string;
	/** The canonical concept(s) whose declaration retires this spelling. */
	retiredBy: string[];
}

/**
 * The exclusion the global census applies, as a machine-derived report.
 *
 * `identifierTerms` drops these spellings because one lexical count cannot
 * separate the canonical sense from the retired one. That exclusion is the
 * widest hole in the sweep, so it is enumerated from the glossary rather than
 * described in prose: each row names the module that owns the canonical sense
 * and the concept that retires the other sense, which is what a per-concept
 * rename slice needs to do the work the census cannot.
 */
function retiredInOneSense(
	glossary: Map<string, GlossaryEntry>,
): OneSenseRow[] {
	const rows: OneSenseRow[] = [];
	for (const [term, entry] of glossary) {
		const retiredBy = [...glossary]
			.filter(([, other]) => other.retires.includes(term))
			.map(([canonical]) => canonical);
		if (retiredBy.length > 0)
			rows.push({ term, owner: entry.owner, retiredBy });
	}
	return rows.sort((a, b) => a.term.localeCompare(b.term));
}

function sourceFiles(): string[] {
	const files: string[] = [];
	for (const dir of ["clients", "tools", "mcp"]) {
		const found = listSourceFiles(path.join(REPO_ROOT, dir), {
			extensions: [".ts"],
			skipDeclarations: true,
		});
		assertNonEmptyScan(`${dir}/ source population`, found.length, 1);
		files.push(...found);
	}
	files.push(path.join(REPO_ROOT, "index.ts"));
	return files;
}

function countIdentifier(source: string, term: string): number {
	const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	return [
		...source.matchAll(
			new RegExp(`(?<![A-Za-z0-9_$])${escaped}(?![A-Za-z0-9_$])`, "g"),
		),
	].length;
}

function census(
	terms: readonly string[],
): Record<string, Record<string, number>> {
	const counts: Record<string, Record<string, number>> = {};
	const files = sourceFiles();
	assertNonEmptyScan(
		"clients/tools/mcp/index.ts source population",
		files.length,
		400,
	);
	for (const file of files) {
		const raw = readWalkedFile(file);
		if (raw === undefined) continue;
		const stripped = stripSource(raw, { strings: "blank" });
		const relative = relativePosix(REPO_ROOT, file);
		for (const term of terms) {
			const count = countIdentifier(stripped, term);
			if (count > 0) (counts[term] ??= {})[relative] = count;
		}
	}
	return counts;
}

